const t = require("fs").readFileSync("/tmp/sx15.txt", "utf8");
const a = JSON.parse(t);
function esc(s) {
  if (s === null || s === undefined) return String(s);
  let out = '"';
  for (const ch of s) {
    const c = ch.codePointAt(0);
    if (ch === "\n") out += "\\n";
    else if (ch === "\t") out += "\\t";
    else if (ch === '"') out += '\\"';
    else if (c < 0x20 || c > 0x7e) out += "\\u" + c.toString(16).padStart(4, "0");
    else out += ch;
  }
  return out + '"';
}
a.forEach((r, i) => console.log(i, esc(r.input), "=>", esc(r.output)));
